<?php if($suspects):?><section><h2 class="text-xl font-bold mb-3">IP con actividad sospechosa en las últimas 24 horas</h2><div class="overflow-x-auto bg-slate-900 border border-amber-900 rounded-xl"><table class="w-full text-sm"><thead><tr class="text-left text-slate-400"><th class="p-3">IP</th><th>Eventos</th><th>Último evento</th><th>Motivos observados</th><th></th></tr></thead><tbody><?php foreach($suspects as $s):?><tr class="border-t border-slate-800"><td class="p-3 font-mono"><?=$e($s['ip'])?></td><td><?=$s['events']?></td><td><?=$e($s['last_event'])?></td><td class="max-w-xl truncate"><?=$e($s['reasons'])?></td><td class="p-2"><form method="post" action="/security/ip-blocks" class="flex gap-2"><?=$csrf->field()?><input type="hidden" name="ip" value="<?=$e($s['ip'])?>"><input type="hidden" name="reason" value="Actividad abusiva detectada: <?=$s['events']?> eventos"><input type="hidden" name="hours" value="24"><button class="bg-amber-700 px-3 py-1.5 rounded">Bloquear 24 h</button></form></td></tr><?php endforeach?></tbody></table></div></section><?php endif?>
<section><h2 class="text-xl font-bold mb-3">Lista de bloqueos</h2><div class="overflow-x-auto bg-slate-900 border border-slate-800 rounded-xl"><table class="w-full text-sm"><thead><tr class="text-left text-slate-400"><th class="p-3">IP</th><th>Estado</th><th>Origen</th><th>Motivo</th><th>Expira</th><th>Agregado por</th><th></th></tr></thead><tbody><?php foreach($blocks as $b):$expired=$b['expires_at']&&strtotime($b['expires_at'])<=time();?><tr class="border-t border-slate-800"><td class="p-3 font-mono"><?=$e($b['ip'])?></td><td><span class="<?=$b['active']&&!$expired?'text-red-400':'text-slate-500'?>"><?=$b['active']&&!$expired?'Bloqueada':($expired?'Expirada':'Retirada')?></span></td><td><?=$e($b['source'])?></td><td class="max-w-md"><?=$e($b['reason'])?></td><td><?=$e($b['expires_at']??'Permanente')?></td><td><?=$e($b['actor']??'Sistema')?></td><td class="p-2"><?php if($b['active']&&!$expired):?><form method="post" action="/security/ip-blocks/remove" onsubmit="return confirm('¿Retirar este bloqueo?')"><?=$csrf->field()?><input type="hidden" name="id" value="<?=$b['id']?>"><button class="bg-emerald-700 px-3 py-1.5 rounded">Desbloquear</button></form><?php endif?></td></tr><?php endforeach?><?php if(!$blocks):?><tr><td colspan="7" class="p-10 text-center text-slate-500">No hay IP bloqueadas.</td></tr><?php endif?></tbody></table></div></section>
<aside class="border border-slate-800 rounded-xl p-4 text-sm text-slate-400"><strong class="text-slate-200">Importante:</strong> esta lista bloquea peticiones en OrionX inmediatamente. Los cambios de UFW/nftables siguen requiriendo autorización administrativa separada para evitar perder el acceso SSH o web.</aside></div>
